import csv

def solve():
    region_units = {}
    try:
        with open('sales.csv', 'r') as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row['product'] == 'widget':
                    region = row['region']
                    units = int(row['units'])
                    region_units[region] = region_units.get(region, 0) + units
    except Exception:
        print("UNSOLVABLE")
        return

    if not region_units:
        print("UNSOLVABLE")
        return

    max_region = max(region_units, key=region_units.get)
    print(max_region)

if __name__ == "__main__":
    solve()

